// Extract data from the webhook payload (e.g., from Google Apps Script or a form)
const input = $input.first().json;
let formData;

try {
  if (input.body) {
    formData = typeof input.body === 'string' ? JSON.parse(input.body) : input.body;
  } else {
    formData = input; // Assuming data is at the top level if no 'body' property
  }
} catch (e) {
  console.error("Error parsing formData:", e, "Input was:", JSON.stringify(input));
  return { json: { success: false, message: "Invalid JSON payload.", errorType: "INVALID_PAYLOAD" } };
}

// --- Input Sanitization and Validation Functions ---
function sanitizeString(str, allowBasicPunctuation = false) {
  if (str === null || typeof str === 'undefined') str = '';
  str = String(str); // Ensure it's a string before regex
  if (allowBasicPunctuation) {
    return str.replace(/[<>\"&%$;()+\\/]+/g, '');
  }
  return str.replace(/[^a-zA-Z0-9-_]/g, '');
}

function sanitizeOtp(str) {
  if (str === null || typeof str === 'undefined') str = '';
  str = String(str);
  return str.replace(/[^0-9]/g, '');
}

// Extract, sanitize, and validate required fields
let errors = [];
const now = new Date();
const processingTimestamp = now.toISOString();

// Order ID
let orderId = (formData.orderId || formData['Order ID'] || '');
orderId = sanitizeString(orderId.toString().trim()); 
if (!orderId) {
  errors.push("Order ID is required.");
} else if (orderId.length > 50) { 
  errors.push("Order ID is too long (max 50 chars).");
} else if (!/^[a-zA-Z0-9-_]+$/.test(orderId)) { 
  errors.push("Order ID contains invalid characters. Only alphanumeric, hyphen, and underscore are allowed.");
}

// Delivery Person Name
let deliveryPersonName = (formData.deliveryPersonName || formData['Delivery Person Name'] || '');
deliveryPersonName = sanitizeString(deliveryPersonName.toString().trim(), true); 
if (!deliveryPersonName) {
  errors.push("Delivery Person Name is required.");
} else if (deliveryPersonName.length > 100) { 
  errors.push("Delivery Person Name is too long (max 100 chars).");
}

// OTP
let otp = (formData.otp || formData['OTP'] || '');
otp = sanitizeOtp(otp.toString().trim()); 
if (!otp) {
  errors.push("OTP is required.");
} else if (!/^[0-9]{4,8}$/.test(otp)) { 
  errors.push("OTP must be 4-8 digits.");
}

// Timestamp from payload (optional, for validation if provided by source)
const incomingTimestampStr = formData.timestamp || null;
let validatedIncomingTimestamp = null;
if (incomingTimestampStr) {
  const parsedDate = new Date(incomingTimestampStr);
  if (isNaN(parsedDate.getTime())) {
    errors.push("Invalid format for provided timestamp. Please use ISO 8601 format.");
  } else {
    const timeDiffMinutes = (now.getTime() - parsedDate.getTime()) / 60000;
    if (timeDiffMinutes > 1440) { // More than 24 hours old
      errors.push("Provided timestamp is too old (older than 24 hours).");
    } else if (timeDiffMinutes < -10) { // 10 minutes in the future (allowing for small clock drifts)
      errors.push("Provided timestamp is from the future.");
    } else {
      validatedIncomingTimestamp = parsedDate.toISOString();
    }
  }
}

if (errors.length > 0) {
  return {
    json: {
      success: false,
      message: "Validation failed: " + errors.join(' '),
      errorType: "INVALID_INPUT",
      validationDetails: errors.join(' '),
      loggedAt: processingTimestamp,
      validInputs: false
    }
  };
}

// Optional fields (sanitize them as well)
const deliveryStatus = sanitizeString((formData.deliveryStatus || formData['Delivery Status'] || "Delivered").toString().trim(), true);
const deliveryNotes = sanitizeString((formData.deliveryNotes || formData['Delivery Notes'] || "").toString().trim(), true); 
const rowId = formData.rowId || formData.row || null; 
const spreadsheetId = sanitizeString((formData.spreadsheetId || '').toString().trim());

return {
  json: {
    orderId,
    deliveryPersonName,
    otp,
    deliveryStatus,
    deliveryNotes,
    rowId,
    spreadsheetId,
    originalTimestamp: validatedIncomingTimestamp, 
    processingTimestamp: processingTimestamp, 
    validInputs: true,
    validationMessage: "All required fields present and seem valid"
  }
};

// Process the Google Sheets lookup results
const lookupResultItem = $input.first(); // Google Sheets v4 lookup returns one item or error
const inputDataFromExtract = $('Extract & Validate Form Data').first().json;

console.log("Lookup result from Google Sheets:", JSON.stringify(lookupResultItem.json));

if (!lookupResultItem.json || Object.keys(lookupResultItem.json).length === 0) { // Check if json is empty or undefined
  return {
    json: {
      ...inputDataFromExtract,
      success: false,
      message: "Order ID not found in the tracking system.",
      errorType: "ORDER_NOT_FOUND",
      orderExists: false
    }
  };
}

const orderData = lookupResultItem.json;

const storedOtp = orderData.otp ? orderData.otp.toString().trim() : null;
const providedOtp = inputDataFromExtract.otp;
const rowId = orderData.rowNumber || inputDataFromExtract.rowId; // Prefer rowNumber from lookup

const otpMatches = storedOtp === providedOtp;

// Placeholder: these fields would come from the Google Sheet if added there
const customerName = orderData.customerName || 'N/A';
const customerPhoneNumber = orderData.customerPhoneNumber || 'N/A';
const deliveryInstructions = orderData.deliveryInstructions || 'None';

return {
  json: {
    ...inputDataFromExtract,
    ...orderData, // data from the sheet (like stored OTP, original address etc.)
    orderId: inputDataFromExtract.orderId, // Ensure this comes from the input form
    rowId, // Corrected rowId
    providedOtp,
    storedOtp,
    otpMatches,
    orderExists: true,
    deliveryTime: inputDataFromExtract.processingTimestamp, // Use consistent timestamp
    // Pass along enriched data
    customerName,
    customerPhoneNumber,
    deliveryInstructions
  }
};

// Placeholder for sending notifications (e.g., SMS to customer)
const processData = $('Process Lookup & Verify OTP').first().json;
console.log(`Placeholder: Send notification for order ${processData.orderId}. Customer: ${processData.customerName}, Phone: ${processData.customerPhoneNumber}`);
// Example: items.push({json: {message: "Notification logic to be implemented here"}}); // If this node should output data
return $input.first().json; // Pass through data from WooCommerce node

// Create success response for delivery person
const processNodeData = $('Process Lookup & Verify OTP').first().json;
return {
  json: {
    success: true,
    message: "Delivery confirmed successfully! Order status updated. Notification (simulated) sent.",
    details: {
      orderId: processNodeData.orderId,
      deliveryPerson: processNodeData.deliveryPersonName,
      timestamp: processNodeData.deliveryTime,
      status: processNodeData.deliveryStatus,
      customerName: processNodeData.customerName || 'N/A',
      customerPhoneNumber: processNodeData.customerPhoneNumber || 'N/A',
      deliveryInstructions: processNodeData.deliveryInstructions || 'None'
    }
  }
};

// Create OTP mismatch error response
const processNodeData = $('Process Lookup & Verify OTP').first().json;
const initialInputData = $('Extract & Validate Form Data').first().json;
return {
  json: {
    success: false,
    message: "Delivery verification failed: OTP does not match. Please check and try again.",
    errorType: "OTP_MISMATCH",
    orderId: processNodeData.orderId,
    loggedAt: initialInputData.processingTimestamp
  }
};

// Create order not found error response from 'Process Lookup & Verify OTP' node
const processNodeData = $('Process Lookup & Verify OTP').first().json;
const initialInputData = $('Extract & Validate Form Data').first().json;
return {
  json: {
    success: false,
    message: processNodeData.message || "Order not found in the tracking system. Please check the Order ID.",
    errorType: "ORDER_NOT_FOUND",
    orderId: processNodeData.orderId,
    loggedAt: initialInputData.processingTimestamp
  }
};

// Create invalid input error response from 'Extract & Validate Form Data' node
const validationNodeData = $('Extract & Validate Form Data').first().json;
return {
  json: {
    success: false,
    message: validationNodeData.message || "Invalid or missing input data. Please provide all required fields.",
    errorType: "INVALID_INPUT",
    validationDetails: validationNodeData.validationDetails,
    loggedAt: validationNodeData.processingTimestamp // Already includes loggedAt
  }
};

const errorInput = $input.first().json;
const originalInput = $('Extract & Validate Form Data').first().json;
const processingTs = originalInput.processingTimestamp || new Date().toISOString();
console.error(`Error looking up order in Google Sheets at ${processingTs}. Order ID: ${originalInput.orderId}. Error:`, JSON.stringify(errorInput));
return { json: { success: false, message: 'Error accessing order data. Please try again later.', errorType: 'GSHEETS_LOOKUP_FAILED', orderId: originalInput.orderId, loggedAt: processingTs } };

const errorInput = $input.first().json;
const otpData = $('Process Lookup & Verify OTP').first().json;
const processingTs = otpData.deliveryTime || new Date().toISOString();
console.error(`Error updating Google Sheets Form Response Log at ${processingTs}. Order ID: ${otpData.orderId}. Error:`, JSON.stringify(errorInput));
return { json: { success: false, message: 'Delivery confirmed, but error logging response. Please contact support.', errorType: 'GSHEETS_LOG_UPDATE_FAILED', orderId: otpData.orderId, loggedAt: processingTs } };

const errorInput = $input.first().json;
const otpData = $('Process Lookup & Verify OTP').first().json;
const processingTs = otpData.deliveryTime || new Date().toISOString();
console.error(`Error updating WooCommerce order at ${processingTs}. Order ID: ${otpData.orderId}. Error:`, JSON.stringify(errorInput));
return { json: { success: false, message: 'Delivery confirmed, but error updating order in WooCommerce. Please contact support.', errorType: 'WOOCOMMERCE_UPDATE_FAILED', orderId: otpData.orderId, loggedAt: processingTs } };

const errorInput = $input.first().json;
const originalData = $('Process Lookup & Verify OTP').first().json; // Data before this GSheet step failed
const processingTs = originalData.deliveryTime || new Date().toISOString();
console.error(`Error updating main tracking sheet on success path at ${processingTs}. Order ID: ${originalData.orderId}. Error:`, JSON.stringify(errorInput));
// Continue the flow as this is a secondary update. Pass through the data from before this failed step.
return originalData;
